create table if not exists public.catalog_categories (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,active boolean default true,created_at timestamptz default now(),unique(organization_id,name));
create table if not exists public.catalog_breeds (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,active boolean default true,created_at timestamptz default now(),unique(organization_id,name));
create table if not exists public.catalog_exit_types (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,active boolean default true,created_at timestamptz default now(),unique(organization_id,name));
alter table public.catalog_categories enable row level security; alter table public.catalog_breeds enable row level security; alter table public.catalog_exit_types enable row level security;
create policy catalog_categories_read on public.catalog_categories for select using (exists(select 1 from public.organization_members m where m.organization_id=organization_id and m.user_id=auth.uid() and m.status='active'));
create policy catalog_breeds_read on public.catalog_breeds for select using (exists(select 1 from public.organization_members m where m.organization_id=organization_id and m.user_id=auth.uid() and m.status='active'));
create policy catalog_exit_types_read on public.catalog_exit_types for select using (exists(select 1 from public.organization_members m where m.organization_id=organization_id and m.user_id=auth.uid() and m.status='active'));
